    topk = set(retrieved[:k])
    return len(topk & set(relevant)) / len(relevant) if relevant else 0.0

def mrr(retrieved, relevant):
    for i, doc in enumerate(retrieved, start=1):
        if doc in relevant:
            return 1.0 / i
    return 0.0

