import numpy as np

def retrieve(query_vec, docs, k=2):
    if not docs:
        return []
    def cos(v):
        nv = np.linalg.norm(v)
        nq = np.linalg.norm(query_vec)
        if nv == 0 or nq == 0:
            return 0.0
        return float(np.dot(query_vec, v) / (nq * nv))
    scored = sorted(docs.items(), key=lambda kv: -cos(kv[1]))
    return [name for name, _ in scored[:k]]

