def chunk_text(text, size=10, overlap=3):
    if not text:
        return []
    if overlap >= size:
        overlap = size - 1
    chunks = []
    start = 0
    while start < len(text):
        end = start + size
        chunks.append(text[start:end])
        if end >= len(text):
            break
        start = end - overlap
    return chunks

