def evaluate_retrieval(cases, k=3):
    if not cases:
        return 0.0
    total = 0.0
    for retrieved, relevant in cases:
        if not relevant:
            continue
        hit = set(retrieved[:k]) & set(relevant)
        total += len(hit) / len(relevant)
    return round(total / len(cases), 4)


