from collections import deque

def find_communities(graph):
    visited = set()
    comps = []
    for node in graph:
        if node in visited:
            continue
        comp = []
        q = deque([node])
        visited.add(node)
        while q:
            cur = q.popleft()
            comp.append(cur)
            for nb in graph[cur]:
                if nb not in visited:
                    visited.add(nb)
                    q.append(nb)
        comps.append(comp)
    return sorted(comps, key=len, reverse=True)


